import sys
from functools import lru_cache

data = sys.stdin.read().split()
s, k = data[0], int(data[1])
n = len(s)
letters = sorted(set(s))
gap = max(k, 1)

def valid(t):
    for i in range(len(t)):
        for j in range(i + 1, min(len(t), i + gap)):
            if t[i] == t[j]:
                return False
    return True

# canonical greedy, written as a plain scan
left = {c: s.count(c) for c in letters}
res = ''
ok = True
for i in range(n):
    best = None
    for c in letters:
        if left[c] == 0 or c in res[max(0, i - gap + 1):i]:
            continue
        if best is None or left[c] > left[best]:
            best = c
    if best is None:
        ok = False
        break
    res += best
    left[best] -= 1

if n <= 12:
    # exhaustive check that a valid arrangement exists exactly when the greedy succeeds
    @lru_cache(maxsize=None)
    def feasible(counts, tail):
        if sum(counts) == 0:
            return True
        for idx, c in enumerate(letters):
            if counts[idx] and c not in tail:
                nc = counts[:idx] + (counts[idx] - 1,) + counts[idx + 1:]
                nt = (tail + c)[-(gap - 1):] if gap > 1 else ''
                if feasible(nc, nt):
                    return True
        return False
    exists = feasible(tuple(s.count(c) for c in letters), '')
    if exists != ok:
        print('MISMATCH')
        sys.exit(0)
if ok and not valid(res):
    print('INVALID')
    sys.exit(0)
print(res if ok else -1)

